const $=s=>document.querySelector(s);let db,nodes=[],current='',query='';const enc=new TextEncoder();const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const parent=p=>p.split('/').slice(0,-1).join('/');const basename=p=>p.split('/').pop();const size=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function transaction(mode,fn){if(window.ServerArchive)return ServerArchive.operations(fn);return new Promise((resolve,reject)=>{const t=db.transaction('nodes',mode);fn(t.objectStore('nodes'));t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('저장을 완료하지 못했습니다.'))})}
async function refresh(){if(window.ServerArchive){nodes=await ServerArchive.nodes();render();return;}nodes=await new Promise((resolve,reject)=>{const r=db.transaction('nodes').objectStore('nodes').getAll();r.onsuccess=()=>resolve(r.result.filter(n=>n.kind!=='meta'));r.onerror=()=>reject(r.error)});render()}
function readme(path){return {path:path+'/README.md',kind:'file',blob:new Blob(['# '+basename(path)+'\n\n수업 자료와 필기를 보관하는 폴더입니다.\n\n- Upload files로 원본 파일을 올려보세요.\n- 하위 폴더를 만들어 주차별로 정리할 수 있습니다.\n- GitHub로 보내기로 폴더 구조를 그대로 보관하세요.\n'],{type:'text/markdown;charset=utf-8'}),date:Date.now()}}
async function addFolder(path){if(nodes.some(n=>n.path===path))throw Error('같은 이름의 폴더 또는 파일이 있습니다.');await transaction('readwrite',s=>{s.put({path,kind:'folder',date:Date.now()});s.put(readme(path))})}
function navigate(p){current=p;query='';$('#search').value='';render()}
function render(){const folders=nodes.filter(n=>n.kind==='folder');const files=nodes.filter(n=>n.kind==='file');$('#folders').textContent=folders.length;$('#files').textContent=files.length;$('#size').textContent=size(files.reduce((a,n)=>a+n.blob.size,0));$('#tree').innerHTML=folders.sort((a,b)=>a.path.localeCompare(b.path,'ko')).map(n=>`<button class="treeitem ${current===n.path?'selected':''}" style="padding-left:${8+(n.path.split('/').length-1)*13}px" data-path="${esc(n.path)}">▱ &nbsp; ${esc(basename(n.path))}</button>`).join('');$('#tree').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(b.dataset.path));$('#crumb').innerHTML='<button data-path="">⌂ 내 아카이브</button>'+current.split('/').filter(Boolean).map((s,i,a)=>`<i> / </i><button data-path="${esc(a.slice(0,i+1).join('/'))}">${esc(s)}</button>`).join('');$('#crumb').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(b.dataset.path));let list=nodes.filter(n=>parent(n.path)===current&&basename(n.path).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(a.kind===b.kind?0:a.kind==='folder'?-1:1)||a.path.localeCompare(b.path,'ko'));$('#count').textContent=list.length+'개 항목';$('#list').innerHTML=list.map((n,i)=>`<div class="row"><button class="name" data-open="${i}"><span class="fileicon ${n.kind==='folder'?'foldericon':''}">${n.kind==='folder'?'▱':'▤'}</span><span>${esc(basename(n.path))}</span></button><span class="muted">${n.kind==='folder'?'폴더':esc(basename(n.path).includes('.')?basename(n.path).split('.').pop().toUpperCase():'파일')}</span><span class="muted">${n.kind==='folder'?'—':size(n.blob.size)}</span><div class="tools">${n.kind==='file'?`<button data-dl="${i}" title="다운로드">↓</button>${window.ServerArchive?`<button data-gh="${i}" title="이 파일만 GitHub로 보내기" aria-label="${esc(basename(n.path))} 파일만 GitHub로 보내기">GitHub로 보내기</button>`:''}`:''}<button data-del="${i}" title="삭제">삭제</button></div></div>`).join('')||'<div class="empty">아직 파일이 없어요. 첫 자료를 올려보세요.</div>';$('#list').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{let n=list[b.dataset.open];n.kind==='folder'?navigate(n.path):download(n.blob,basename(n.path))});$('#list').querySelectorAll('[data-dl]').forEach(b=>b.onclick=()=>{let n=list[b.dataset.dl];download(n.blob,basename(n.path))});$('#list').querySelectorAll('[data-gh]').forEach(b=>b.onclick=()=>document.dispatchEvent(new CustomEvent('github-send-file',{detail:{path:list[b.dataset.gh].path}})));$('#list').querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{let n=list[b.dataset.del];if(!confirm(`${basename(n.path)}${n.kind==='folder'?' 및 하위 파일을':''} 삭제할까요?`))return;try{await transaction('readwrite',s=>nodes.filter(x=>x.path===n.path||x.path.startsWith(n.path+'/')).forEach(x=>s.delete(x.path)));await refresh();toast('삭제했습니다.')}catch(e){toast(e.message)}});const rm=nodes.find(n=>n.path===current+'/README.md');$('#readme').textContent=current?'README.md를 불러오는 중…':'나의 수업 아카이브\n\n학기 → 과목 → 주차 순서로 자료를 정리해보세요.\n폴더를 열면 파일과 안내 문서를 확인할 수 있습니다.';if(current){const shown=current;if(rm)rm.blob.text().then(t=>{if(current===shown)$('#readme').textContent=t});else $('#readme').textContent='이 폴더에는 README.md가 없습니다.'}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function upload(files){const batch=Array.from(files);if(!batch.length)return;try{const target=current;const entries=[];for(const f of batch){if(/[\\/\x00-\x1f]/.test(f.name))throw Error('파일 이름을 확인해주세요.');const path=(target?target+'/':'')+f.name;const existing=nodes.find(n=>n.path===path);if(existing?.kind==='folder')throw Error('동일한 이름의 폴더가 있습니다: '+f.name);if(existing&&!confirm(f.name+' 파일을 덮어쓸까요?'))continue;entries.push({path,kind:'file',blob:f,date:Date.now()})}await transaction('readwrite',s=>entries.forEach(n=>s.put(n)));await refresh();toast(entries.length+'개 파일을 원본 그대로 저장했습니다.')}catch(e){toast('업로드 실패: '+e.message)}finally{$('#picker').value=''}}
$('#upload').onclick=()=>$('#picker').click();$('#picker').onchange=e=>upload(e.target.files);$('#search').oninput=e=>{query=e.target.value;render()};$('#home').onclick=()=>navigate('');$('#newfolder').onclick=$('#sideadd').onclick=()=>{$('#foldername').value='';$('#dialog').showModal();$('#foldername').focus()};$('#cancel').onclick=()=>$('#dialog').close();$('#folderform').onsubmit=async e=>{e.preventDefault();let name=$('#foldername').value.trim();if(!name||name==='.'||name==='..'||/[\\/:*?"<>|\x00-\x1f]/.test(name)||/[. ]$/.test(name)){toast('폴더 이름에 특수문자나 끝의 마침표를 사용할 수 없습니다.');return}try{await addFolder((current?current+'/':'')+name);await refresh();$('#dialog').close();toast('폴더와 README.md를 만들었습니다.')}catch(e){toast(e.message)}};for(const name of ['dragenter','dragover'])$('#drop').addEventListener(name,e=>{e.preventDefault();$('#drop').classList.add('over')});$('#drop').ondragleave=()=>$('#drop').classList.remove('over');$('#drop').ondrop=e=>{e.preventDefault();$('#drop').classList.remove('over');upload(e.dataTransfer.files)};window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});function crc(bytes){let c=0xffffffff;for(let b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}function header(len){return new DataView(new ArrayBuffer(len))}
async function exportZip(){const button=$('#export');button.disabled=true;button.textContent='내보내는 중…';try{const local=[],central=[];let offset=0;const snapshot=[...nodes];if(snapshot.length>65535)throw Error('ZIP 항목 수가 너무 많습니다.');for(const n of snapshot){let name=enc.encode(n.path+(n.kind==='folder'?'/':''));let blob=n.kind==='folder'?new Blob([]):n.blob;let bytes=new Uint8Array(await blob.arrayBuffer());if(bytes.length>0xffffffff||offset+bytes.length>0xffffffff)throw Error('ZIP은 4GB 미만으로 내보내주세요.');let checksum=crc(bytes);let h=header(30);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,0x21,true);h.setUint32(14,checksum,true);h.setUint32(18,bytes.length,true);h.setUint32(22,bytes.length,true);h.setUint16(26,name.length,true);local.push(h.buffer,name,blob);let c=header(46);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,0x21,true);c.setUint32(16,checksum,true);c.setUint32(20,bytes.length,true);c.setUint32(24,bytes.length,true);c.setUint16(28,name.length,true);c.setUint32(38,n.kind==='folder'?16:0,true);c.setUint32(42,offset,true);central.push(c.buffer,name);offset+=30+name.length+bytes.length}const cb=new Blob(central);let end=header(22);end.setUint32(0,0x06054b50,true);end.setUint16(8,snapshot.length,true);end.setUint16(10,snapshot.length,true);end.setUint32(12,cb.size,true);end.setUint32(16,offset,true);download(new Blob([...local,cb,end.buffer],{type:'application/zip'}),'classkeep-archive.zip');toast('폴더 구조를 유지한 ZIP을 내보냈습니다.')}catch(e){toast('내보내기 실패: '+e.message)}finally{button.disabled=false;button.textContent='↓ 전체 ZIP 내보내기'}}$('#export').onclick=exportZip;
async function init(){if(window.ServerArchive)return ServerArchive.init();try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('classkeep-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('nodes',{keyPath:'path'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});await refresh();const seeded=await new Promise((resolve,reject)=>{const r=db.transaction('nodes').objectStore('nodes').get('__initialized__');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!seeded){for(const p of ['2026-2학기','2026-2학기/인공지능','2026-2학기/인공지능/01주차','2026-2학기/인공지능/02주차','2026-2학기/자료구조'])await addFolder(p);await transaction('readwrite',s=>s.put({path:'__initialized__',kind:'meta'}));await refresh()}navigate('2026-2학기/인공지능')}catch(e){toast('저장소를 열 수 없습니다. 브라우저 저장 공간 설정을 확인해주세요.');$('#upload').disabled=true;$('#newfolder').disabled=true;$('#export').disabled=true}}
init();

